for(const level of Object.keys(MOCK_BANK)) MOCK_BANK[level].push(...MOCK_BANK_EXTRA[level]);
let bankRun=null;
function showBankQuestion(){
 if(!bankRun)return;
 if(bankRun.index>=bankRun.questions.length){finishBankRun();return}
 const q=bankRun.questions[bankRun.index];
 const answered=bankRun.answers[bankRun.index];
 const left=bankRun.questions.length-bankRun.index-1;
 v.innerHTML=`<div class="card"><p class="note">JLPT ${bankRun.level} · 20-question practice exam · Question ${bankRun.index+1} / ${bankRun.questions.length}</p><div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap"><b>Question ${bankRun.index+1}</b><span class="note">${bankRun.answers.filter(x=>x!==null).length} answered · ${left} remaining</span></div><div style="height:7px;background:var(--soft);border-radius:8px;margin:10px 0 18px;overflow:hidden"><div style="height:100%;width:${((bankRun.index+1)/bankRun.questions.length)*100}%;background:var(--ac)"></div></div><h3>${q[0]}</h3><div class="ch">${q[1].map((o,i)=>`<button style="${answered===i?"border:2px solid var(--ac);background:var(--soft);font-weight:700":""}" onclick="chooseBankAnswer(${i})">${String.fromCharCode( A=65+i)}. ${o}${answered===i?" ✓":""}</button>`).join("")}</div><p class="note">${answered===null?"Select one answer. Your answers are not revealed until you submit the exam.":"Answer saved. You can change it before submission."}</p><div style="display:flex;justify-content:space-between;gap:8px;margin-top:12px"><button onclick="bankPrev()" ${bankRun.index===0?"disabled":""}>← Previous</button><button class="p" onclick="bankNext()">${bankRun.index===bankRun.questions.length-1?"Submit exam":"Next →"}</button></div></div>`;
}
window.startLevelMock=(level)=>{
 const questions=shuf((MOCK_BANK[level]||[]).slice());
 if(!questions.length){toast("Question bank is not available.");return;}
 bankRun={level,questions,index:0,answers:Array(questions.length).fill(null)};
 showBankQuestion();
};
window.chooseBankAnswer=i=>{if(!bankRun)return;bankRun.answers[bankRun.index]=i;showBankQuestion()};
window.bankNext=()=>{if(!bankRun)return;if(bankRun.index<bankRun.questions.length-1){bankRun.index++;showBankQuestion()}else finishBankRun()};
window.bankPrev=()=>{if(!bankRun||bankRun.index===0)return;bankRun.index--;showBankQuestion()};
function finishBankRun(){
 if(!bankRun)return;
 const run=bankRun;bankRun=null;let correct=0;
 run.questions.forEach((q,i)=>{if(run.answers[i]===q[2])correct++});
 const score=Math.round(correct/run.questions.length*100);
 (S.mocks[run.level]=S.mocks[run.level]||[]).push(score);save();
 v.innerHTML=`<div class="card"><h2>JLPT ${run.level} · Practice Exam Result</h2><div class="big">${score}%</div><p>${correct} / ${run.questions.length} correct</p><p class="note">One combined ${run.questions.length}-question practice paper, made by combining the former Paper 1 and Paper 2 question banks. This is an original JLPT-style practice exam, not an official full-length JLPT paper or scaled JLPT score.</p><button class="p" onclick="showMockPaperMenu('${f.level}')">Back to ${run.level} exam</button> <button onclick="mockTest()">Choose another level</button></div><div class="card"><h3>Answer review</h3>${run.questions.map((q,i)=>`<p>${run.answers[i]===q[2]?"✅":"❌"} <b>Question ${i+1}: ${q[0]}</b><br><span class="note">Your answer: ${run.answers[i]===null?"Not answered":q[1][run.answers[i]]} · Correct answer: ${q[1][q[2]]}<br>${q[3]}</span></p>`).join("")}</div>`;
};

let selectedMockLevel="N5";
const MOCK_EXAM_FORMAT={
 N5:{total:90,sections:[["Vocabulary",20],["Grammar & Reading",40],["Listening",30]]},
 N4:{total:115,sections:[["Vocabulary",25],["Grammar & Reading",55],["Listening",35]]},
 N3:{total:140,sections:[["Vocabulary",30],["Grammar & Reading",70],["Listening",40]]},
 N2:{total:155,sections:[["Language Knowledge & Reading",105],["Listening",50]]},
 N1:{total:165,sections:[["Language Knowledge & Reading",110],["Listening",55]]}
};
function startQuestionBankPaper(level,paper){
 if(level==="N5"&&paper>=1&&paper<=20){window.startFull(paper,"N5");return;}
 if(level==="N4"&&paper>=1&&paper<=20){window.startFull(paper,"N4");return;}
 if(level==="N3"&&paper>=1&&paper<=20){window.startFull(paper,"N3");return;}
 if(level==="N2"&&paper>=1&&paper<=20){window.startFull(paper,"N2");return;}
 if(level==="N1"&&paper>=1&&paper<=20){window.startFull(paper,"N1");return;}
 toast("This exam paper is being prepared. Please choose an available paper.");
}
function showMockPaperMenu(level){
 selectedMockLevel=level;
 const fmt=MOCK_EXAM_FORMAT[level];
 const timing=fmt.sections.map(([name,mins])=>`<p>${name}: <b>${mins} minutes</b></p>`).join("");
 const cards=Array.from({length:20},(_,i)=>{
  const paper=i+1,ready=(["N5","N4","N3","N2","N1"].includes(level)&&paper>=1&&paper<=20);
  return `<div class="card" style="padding:12px"><div style="display:flex;justify-content:space-between;align-items:center;gap:8px"><b>${level} · Question Paper ${paper}</b><span class="note">${ready?"Available":"In preparation"}</span></div><p class="note">${ready?`Full timed ${level} practice exam · 60 questions · Paper ${paper}`:"Separate full-length exam paper"}</p><button ${ready?'class="p"':"disabled"} onclick="startQuestionBankPaper('${level}',${paper})">${ready?"Start exam →":"Coming soon"}</button></div>`;
 }).join("");
 v.innerHTML=`<div class="card"><button onclick="mockTest()">← All JLPT levels</button><h2>JLPT ${level} · Question Bank</h2><p>Choose one complete exam paper. Each paper is separate; finish it and review your result before selecting another.</p>${timing}<p><b>JLPT exam duration: ${fmt.total} minutes</b></p><p class="note">20 separate exam papers are planned for this level. N5, N4, N3, N2 and N1 Papers 1–20 are available in this build. N1 papers use original N1-level practice question pools.</p></div>${cards}`;
}
function mockTest(){
 const levels=["N5","N4","N3","N2","N1"];
 v.innerHTML=`<div class="card"><h2>📝 JLPT Exam Question Bank</h2><p>Each level contains 20 separate exam papers. Select a level, then choose an individual paper. These are complete exam papers—not a 20-question quiz.</p><p><b>100 planned exam papers across N5–N1.</b></p></div>
 ${levels.map(l=>{const f=MOCK_EXAM_FORMAT[l];return `<div class="card"><h3>JLPT ${l} · 20 exam papers</h3>${f.sections.map(([n,m])=>`<p>${n}: ${m} minutes</p>`).join("")}<p><b>Total exam time: ${f.total} minutes</b></p><button class="p" onclick="showMockPaperMenu('${l}')">Open ${l} question bank →</button></div>`}).join("")}
 ${histCard()}`;
}
