function listening(){
 const c=LT(),item=LISTEN_ITEMS[listenIndex],opts=item.choices[S.lang]||item.choices.en;
 v.innerHTML=`<div class="card"><h2>🎧 ${c[0]}</h2><p class="note">${c[1]}</p><div class="note">NihongoSetu listening practice · Japanese audio plays inside this app. Use the normal or slow button to listen again.</div><p class="note">JLPT N5 · ${listenIndex+1}/${LISTEN_ITEMS.length}</p><div style="text-align:center;font-size:30px;padding:10px">🎧</div><div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap"><button class="p" onclick="playListening(1)">${c[2]}</button><button onclick="playListening(.72)">${c[3]}</button></div><div style="text-align:center;margin:12px"><button onclick="listenTranscript=!listenTranscript;listening()">${listenTranscript?c[5]:c[4]}</button></div>${listenTranscript?`<div class="note" style="text-align:center"><b>${item.jp}</b><br>${item.romaji}<br>${item.meaning[S.lang]||item.meaning.en}</div>`:""}<hr><b>${c[6]}</b>${opts.map((o,i)=>`<button style="display:block;width:100%;margin:8px 0;text-align:left;${listenChoice===i?"border-color:var(--ac)":""}" onclick="listenChoice=${i};listenResult='';listening()">${String.fromCharCode(65+i)}. ${o}</button>`).join("")}<button class="p" onclick="checkListening()">${c[7]}</button>${listenResult?`<p>${listenResult}</p>`:""}<div style="display:flex;justify-content:space-between;margin-top:12px"><button onclick="listenIndex=(listenIndex+LISTEN_ITEMS.length-1)%LISTEN_ITEMS.length;listenChoice=-1;listenResult='';listenTranscript=false;listening()">← Previous</button><button onclick="listenIndex=(listenIndex+1)%LISTEN_ITEMS.length;listenChoice=-1;listenResult='';listenTranscript=false;listening()">Next →</button></div></div>`;
}
window.playListening=rate=>{if(!("speechSynthesis" in window)){toast("Speech audio unavailable. Try Chrome.");return;}try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(LISTEN_ITEMS[listenIndex].jp);u.lang="ja-JP";u.rate=rate;const voices=speechSynthesis.getVoices()||[];const ja=voices.find(x=>/^ja([-_]|$)/i.test(x.lang));if(ja)u.voice=ja;speechSynthesis.speak(u);}catch(e){toast("Speech audio unavailable. Try Chrome.");}};
window.checkListening=()=>{if(listenChoice<0){toast(LT()[10]);return;}listenResult=listenChoice===LISTEN_ITEMS[listenIndex].answer?LT()[8]:LT()[9];listening();};

