const GRAMMAR_DATA={"N5":[["です","です","Polite sentence ending; identifies or describes something.","わたしは学生です。","I am a student."],["は","は","Marks the topic of a sentence.","これは本です。","This is a book."],["か","か","Turns a statement into a question.","これは何ですか。","What is this?"],["の","の","Shows possession or connects nouns.","これはわたしのかばんです。","This is my bag."],["も","も","Means “also” or “too”.","わたしも行きます。","I will go too."],["を","を","Marks the direct object of an action.","水を飲みます。","I drink water."],["に","に","Marks a time, destination or point of existence.","七時に起きます。","I wake up at seven."],["で","で","Marks the place where an action happens or a means.","図書館で勉強します。","I study at the library."],["ません","ません","Negative polite verb form.","肉を食べません。","I do not eat meat."],["たいです","たいです","Expresses what the speaker wants to do.","日本へ行きたいです。","I want to go to Japan."],["てください","てください","A polite request: please do something.","ここに名前を書いてください。","Please write your name here."],["てもいいです","てもいいです","Asks or gives permission.","ここに座ってもいいですか。","May I sit here?"]],"N4":[["なければなりません","なければなりません","Expresses obligation: must do.","毎日勉強しなければなりません。","I must study every day."],["なくてもいいです","なくてもいいです","Says something is not necessary.","明日は来なくてもいいです。","You do not have to come tomorrow."],["たことがある","たことがある","Describes past experience.","富士山に登ったことがあります。","I have climbed Mount Fuji."],["たり～たりする","たり～たりする","Lists representative actions.","休みの日は本を読んだり、映画を見たりします。","On days off I read books, watch movies, and so on."],["ながら","ながら","Two actions done at the same time.","音楽を聞きながら勉強します。","I study while listening to music."],["そうです（様態）","そうです","Indicates appearance or something that seems likely.","このケーキはおいしそうです。","This cake looks delicious."],["と思います","と思います","Expresses an opinion or thought.","明日は雨だと思います。","I think it will rain tomorrow."],["かもしれません","かもしれません","Expresses possibility or uncertainty.","彼は来ないかもしれません。","He might not come."],["てしまう","てしまう","Expresses completion or regret.","財布を忘れてしまいました。","I unfortunately forgot my wallet."],["ために","ために","Expresses purpose or reason.","日本で働くために、日本語を勉強しています。","I study Japanese in order to work in Japan."]],"N3":[["ことにする","ことにする","Expresses a decision made by the speaker.","毎朝走ることにしました。","I have decided to run every morning."],["ことになる","ことになる","Expresses a decision or arrangement made by others or circumstances.","来月から大阪で働くことになりました。","It has been decided that I will work in Osaka from next month."],["ようにする","ようにする","Describes making an effort or forming a habit.","毎日漢字を復習するようにしています。","I make a point of reviewing kanji every day."],["ようになる","ようになる","Describes a change or new ability.","日本語の新聞が読めるようになりました。","I have become able to read Japanese newspapers."],["ばかり","ばかり","Indicates doing nothing but something, or having just done it depending on form.","弟はゲームばかりしています。","My younger brother does nothing but play games."],["わけではない","わけではない","Softens or partially denies a generalization.","日本料理が嫌いなわけではありません。","It is not that I dislike Japanese food."],["はずだ","はずだ","Expresses an expectation based on reason or information.","田中さんはもう着いたはずです。","Tanaka should have arrived by now."],["おかげで","おかげで","Indicates a positive result thanks to something.","先生のおかげで合格できました。","Thanks to my teacher, I was able to pass."],["せいで","せいで","Indicates a negative result caused by something.","雨のせいで試合が中止になりました。","The match was cancelled because of the rain."],["一方で","一方で","Introduces a contrasting side or simultaneous trend.","都会は便利な一方で、生活費が高いです。","Cities are convenient, but living costs are high."]],"N2":[["に違いない","に違いない","Expresses a strong inference: must surely be.","電気がついている。まだ家にいるに違いない。","The light is on. They must still be home."],["わけにはいかない","わけにはいかない","Indicates that circumstances or responsibility make an action impossible.","明日は試験なので、休むわけにはいきません。","I cannot take the day off because I have an exam tomorrow."],["ものの","ものの","Means “although”; introduces an unexpected contrast.","薬を飲んだものの、熱は下がりません。","Although I took medicine, my fever did not go down."],["に応じて","に応じて","Means “according to” or “in response to”.","能力に応じてクラスを分けます。","We divide classes according to ability."],["をめぐって","をめぐって","Indicates a topic or dispute around which discussion occurs.","新しい計画をめぐって意見が分かれています。","Opinions are divided over the new plan."],["に伴って","に伴って","Expresses a change that occurs along with another change.","人口の増加に伴って、交通量も増えました。","Traffic also increased along with population growth."],["次第","次第","Means “as soon as” when attached to a verb stem.","詳細が分かり次第、ご連絡します。","I will contact you as soon as I know the details."],["かねない","かねない","Indicates a real possibility of an undesirable result.","このままでは事故になりかねません。","If this continues, it could lead to an accident."],["に限らず","に限らず","Means “not limited to”; extends a statement beyond one group.","若者に限らず、多くの人が利用しています。","Many people use it, not only young people."],["とは限らない","とは限らない","Says something is not necessarily always true.","高いものが必ずしも良いとは限りません。","Expensive things are not necessarily good."]],"N1":[["いかんによって","いかんによって","Indicates that a result depends on a particular matter or condition.","結果いかんによっては、計画を変更します。","Depending on the result, we may change the plan."],["を禁じ得ない","を禁じ得ない","Expresses an emotion that cannot be suppressed.","その知らせに驚きを禁じ得ません。","I cannot help feeling surprised by the news."],["に即して","に即して","Means in accordance with or based on a standard or reality.","現状に即して対策を見直す必要があります。","We need to review measures in light of the current situation."],["を余儀なくされる","を余儀なくされる","Means to be forced to do something due to circumstances.","大雨で計画の変更を余儀なくされました。","Heavy rain forced us to change the plan."],["にたえない","にたえない","Expresses that something is unbearable or, in another usage, deeply felt.","彼の努力には敬意にたえません。","His efforts are truly worthy of deep respect."],["と相まって","と相まって","Means combined with; two factors work together.","技術の進歩と相まって、生活は便利になりました。","Combined with technological progress, life has become more convenient."],["をおいてほかにない","をおいてほかにない","Emphasizes that there is no alternative except the stated one.","この仕事を任せられる人は彼をおいてほかにいません。","There is no one other than him who can be entrusted with this work."],["ならでは","ならでは","Expresses a quality unique to a person, place or thing.","これは京都ならではの景色です。","This is scenery unique to Kyoto."],["にかたくない","にかたくない","Means it is not difficult to imagine or understand.","彼がどれほど努力したかは想像にかたくありません。","It is easy to imagine how hard he worked."],["んがため（に）","んがため（に）","A formal literary expression meaning “in order to”; attaches to the verb negative stem, with する becoming せんがため.","夢を実現せんがため、彼は努力を続けた。","In order to realize his dream, he continued his efforts."]]};

let grammarLevel="N5";
function grammarSection(){
  const levels=["N5","N4","N3","N2","N1"];
  const rows=GRAMMAR_DATA[grammarLevel]||[];
  v.innerHTML=`<div class="card grammar-intro"><h2>📘 JLPT Grammar Guide · ${grammarLevel}</h2>
  <p>Study grammar patterns with meanings, Japanese examples and English translations. Choose your JLPT level below.</p>
  <p class="note">Study guide aligned to JLPT level descriptions and grammar question formats. This is not an official exhaustive JLPT grammar list.</p>
  <div class="grammar-levels">${levels.map(l=>`<button class="${l===grammarLevel?"p":""}" onclick="grammarLevel='${l}';grammarSection()">${l}</button>`).join("")}</div></div>
  <div class="grammar-count">${rows.length} grammar patterns · ${grammarLevel}</div>
  ${rows.map((g,i)=>`<article class="card grammar-item"><div class="grammar-head"><span class="grammar-no">${String(i+1).padStart(2,"0")}</span><div><h3>${g[0]}</h3><div class="grammar-reading">${g[1]}</div></div></div><p><b>Meaning / Usage</b><br>${g[2]}</p><div class="grammar-example"><b>Example</b><p lang="ja">${g[3]}</p><span>${g[4]}</span></div></article>`).join("")}
  <div class="card"><b>JLPT grammar question practice</b><p class="note">The official JLPT describes grammar item types as selecting the appropriate grammar form, sentence composition, and text grammar.</p></div>`;
}

