  if(!d){d=document.createElement("div");d.id="toast";d.style.cssText="position:fixed;left:12px;right:12px;bottom:84px;background:var(--tx);color:var(--bg);padding:10px 14px;border-radius:10px;z-index:9;font-size:14px";document.body.appendChild(d)}
