const jp=s=>s.replace(/\([^)]*\)/g,"").replace(/[A-Za-z0-9’'“”:=,.?🔊]+/g," ").replace(/\s+/g," ").trim();
const speak=x=>{
  const text=String(x||"").trim();
  if(!text)return;
  if(!("speechSynthesis" in window) || !("SpeechSynthesisUtterance" in window)){
    toast("This browser does not support text-to-speech. Open this file in Google Chrome.");
    return;
  }
  try{
    const synth=window.speechSynthesis;
    synth.cancel();
    loadV();
    const u=new SpeechSynthesisUtterance(text);
    u.lang="ja-JP";u.rate=0.82;u.pitch=1;u.volume=1;
    if(VO)u.voice=VO;
    u.onerror=e=>{
      const code=e&&e.error?e.error:"unknown";
      if(code==="voice-unavailable" || code==="language-unavailable"){
        toast("Japanese voice is not installed. Install a Japanese voice in Android Text-to-speech settings.");
      }else if(code==="not-allowed"){
        toast("Audio playback was blocked. Tap Hear again in Chrome.");
      }else{
        toast("Japanese audio failed ("+code+"). Check Android Text-to-speech settings.");
      }
    };
    setTimeout(()=>{
      try{
        if(VO)u.voice=VO;
        synth.speak(u);
        if(!VO)toast("No Japanese voice found. Trying the default voice; install a Japanese voice for correct pronunciation.");
      }catch(err){toast("Could not start speech. Check Android Text-to-speech settings.");}
    },120);
  }catch(e){toast("Text-to-speech could not start. Try Google Chrome.");}
};
