async function nsRegister(){
 const status=document.getElementById('ns-auth-status');
 const email=(document.getElementById('ns-auth-email')?.value||'').trim();
 const password=document.getElementById('ns-auth-password')?.value||'';
 if(!email||password.length<6){status.textContent='Enter a valid email and a password with at least 6 characters.';return;}
 status.textContent='Creating your account…';
 try{
   const cred=await window.nsAuth.createUserWithEmailAndPassword(email,password);
   await window.nsDb.collection('users').doc(cred.user.uid).set({email:cred.user.email,displayName:(email.split('@')[0]||'Student'),createdAt:firebase.firestore.FieldValue.serverTimestamp()});
   status.textContent='Account created successfully. You are signed in.';
   accountSection();
 }catch(e){status.textContent=nsFriendlyAuthError(e);}
}
async function nsSignIn(){
 const status=document.getElementById('ns-auth-status');
 const email=(document.getElementById('ns-auth-email')?.value||'').trim();
 const password=document.getElementById('ns-auth-password')?.value||'';
 if(!email||!password){status.textContent='Enter your email address and password.';return;}
 status.textContent='Signing in…';
 try{
   const cred=await window.nsAuth.signInWithEmailAndPassword(email,password);
   const ref=window.nsDb.collection('users').doc(cred.user.uid);
   const snap=await ref.get();
   if(!snap.exists) await ref.set({email:cred.user.email,displayName:(email.split('@')[0]||'Student'),createdAt:firebase.firestore.FieldValue.serverTimestamp()});
   accountSection();
 }catch(e){status.textContent=nsFriendlyAuthError(e);}
}
async function nsSignOut(){try{await window.nsAuth.signOut();accountSection();}catch(e){toast(nsFriendlyAuthError(e));}}
function nsFriendlyAuthError(e){
 const c=e&&e.code||'';
 const map={'auth/email-already-in-use':'This email already has an account. Try Sign In.','auth/invalid-email':'Please enter a valid email address.','auth/weak-password':'Choose a stronger password (at least 6 characters).','auth/user-not-found':'No account found. Register first.','auth/wrong-password':'Incorrect password.','auth/invalid-credential':'Email or password is incorrect.','auth/too-many-requests':'Too many attempts. Wait a while and try again.','auth/unauthorized-domain':'This website domain is not authorized in Firebase Authentication settings.','permission-denied':'Firestore denied the profile write. Check the published Firestore security rules.'};
 return map[c]||('Could not complete the request ('+c+'). Check your internet connection and Firebase settings.');
}

