const KANJI_TARGETS={
 N5:{individual:80,cumulative:80,scope:"Basic numbers, directions, time and everyday essentials"},
 N4:{individual:166,cumulative:246,scope:"Basic daily life, family, travel and elementary activities"},
 N3:{individual:367,cumulative:613,scope:"Intermediate vocabulary, everyday work and standard articles"},
 N2:{individual:367,cumulative:980,scope:"Business settings, general news, essays and conversational depth"},
 N1:{individual:117,cumulative:1097,scope:"Advanced Japanese"}
};
const KANJI_LEVEL_COUNTS={N5:80,N4:166,N3:367,N2:367,N1:117};
const KANJI_FULL_CACHE={};
async function getFullKanji(level){
 if(KANJI_FULL_CACHE[level])return KANJI_FULL_CACHE[level];
 const url="https://cdn.jsdelivr.net/gh/evanclan/OpenJLPT@main/data/json/kanji/"+level.toLowerCase()+".json";
 const response=await fetch(url);
 if(!response.ok)throw new Error("Kanji data download failed: "+response.status);
 const data=await response.json();
 if(!Array.isArray(data))throw new Error("Invalid kanji data");
 const rows=data.slice(0,KANJI_LEVEL_COUNTS[level]).map(x=>[
  x.character,(x.kunyomi||[]).join("・"),(x.onyomi||[]).join("・")+" / "+(x.kunyomi||[]).join("・"),
  (x.meanings||[]).join("; "), (x.words||[]).slice(0,8).join("・")
 ]);
 if(rows.length!==KANJI_LEVEL_COUNTS[level])throw new Error("The source list is shorter than the selected target");
 KANJI_FULL_CACHE[level]=rows;
 return rows;
}
let kanjiLevel="N5",kanjiQuery="";
async function kanjiSection(){
 const level=kanjiLevel, learned=S.kanjiLearned||[];
 v.innerHTML=`<div class="card"><h2>字 Kanji Library</h2><p class="note">Loading ${level} kanji list…</p></div>`;
 let list=[],sourceError=false;
 try{list=await getFullKanji(level)}catch(err){sourceError=true;list=KANJI_DATA[level]||[];}
 if(level!==kanjiLevel)return;
 const filtered=list.map((k,i)=>({k,i})).filter(({k})=>!kanjiQuery||k.join(" ").toLowerCase().includes(kanjiQuery.toLowerCase()));
 const cards=filtered.map(({k,i})=>{
  const readings=KANJI_READING_EXAMPLES[k[0]]||[];
  const on=k[2].split("/")[0]||"—", kun=k[2].split("/")[1]||"—";
  return `<article class="card kanji-card"><div class="kanji-card-head"><div class="kanji-symbol"><span>${esc(k[0]||"")}</span><rt>${esc(k[1]||"")}</rt></div><div class="kanji-info"><b>${esc(localKanji(k[0],k[3]))}</b><div class="kanji-meta">On-yomi (音読み): ${esc(on)}</div><div class="kanji-meta">Kun-yomi (訓読み): ${esc(kun)}</div></div></div><p class="kanji-example"><b>Example words:</b> ${esc(k[4]||"—")}</p><p class="kanji-example"><b>Reading notes:</b> ${esc(readings[0]||"Use the readings above in compounds.")} ${esc(readings[1]||"Readings may vary by word.")}</p><div class="kanji-actions"><button onclick="speak('${k[0]}')">🔊 Listen</button><button class="${learned.includes(kanjiLevel+":"+i)?"p":""}" onclick="toggleKanji(${i})">${learned.includes(kanjiLevel+":"+i)?"✓ Learned":"Mark learned"}</button></div></article>`;
 }).join("");
 v.innerHTML=`<div class="card"><h2>字 Kanji Library</h2><p class="note">All 1,097 selected kanji are grouped by level. Search by character, reading or meaning.</p>
 <select id="kanjiLevel" style="width:100%">${["N5","N4","N3","N2","N1"].map(l=>`<option value="${l}" ${l===kanjiLevel?"selected":""}>JLPT ${l} · ${KANJI_TARGETS[l].individual} kanji</option>`).join("")}</select>
 <p class="note">Dataset: OpenJLPT / KANJIDIC2-derived kanji data. Level assignments are community study estimates, not official JLPT lists.</p>
 <p><b>${kanjiLevel} target</b><br>Level count: ${KANJI_TARGETS[kanjiLevel].individual}<br>Cumulative total: ${KANJI_TARGETS[kanjiLevel].cumulative}<br><span class="note">${KANJI_TARGETS[kanjiLevel].scope}</span></p>
 <input id="kanjiSearch" value="${esc(kanjiQuery)}" placeholder="Search kanji, reading or meaning"><p class="note">${filtered.length} of ${list.length} kanji shown · ${learned.filter(x=>x.startsWith(kanjiLevel+":")).length} marked learned.</p>
 ${sourceError?`<p class="note">Could not load the complete dataset. Showing the ${list.length} built-in starter entries; connect to the internet and retry.</p>`:""}
 </div><section class="kanji-list">${cards||`<div class="card">No matching kanji.</div>`}</section>
 <p class="note">Total target across all five levels: 1,097 kanji. Attribution: OpenJLPT, KANJIDIC2, JMdict and Jonathan Waller's community JLPT classifications. Dataset licence: CC BY-SA 4.0; see OpenJLPT NOTICE for upstream attribution.</p>`;
 document.getElementById("kanjiLevel").onchange=e=>{kanjiLevel=e.target.value;kanjiQuery="";kanjiSection()};
 document.getElementById("kanjiSearch").oninput=e=>{kanjiQuery=e.target.value;kanjiSection()};
}
window.toggleKanji=i=>{const a=S.kanjiLearned||[],key=kanjiLevel+":"+i,at=a.indexOf(key);if(at>=0)a.splice(at,1);else a.push(key);S.kanjiLearned=a;save();kanjiSection()};

function levels(){
 const cards=LV.map(l=>`<div class="card"><h3>JLPT ${l}</h3><p class="note">${({N5:"Beginner",N4:"Elementary",N3:"Intermediate",N2:"Upper-intermediate",N1:"Advanced"})[l]} level</p><p><b>${(W[l]||[]).length}</b> starter vocabulary entries · <b>${KANJI_TARGETS[l].individual}</b> kanji in this level</p>${l==="N5"?`<p class="note">${passes("N5")}/10 passing N5 mock exams</p>`:`<p class="note">Learning library is accessible. Full reviewed course and mock-test bank are still being developed.</p>`}<button class="p" onclick="openLevel('${l}')">Open ${l} level</button></div>`).join("");
 v.innerHTML=`<div class="card"><h2>📘 All JLPT Levels</h2><p>All five levels are now accessible. Choose a level to open its vocabulary, kanji and video lessons.</p><p class="note">Kanji targets: 80 + 166 + 367 + 367 + 117 = 1,097. Other learning content remains in staged development.</p></div>${cards}<p class="note">N5 is the first mock-test release. N4–N1 mock tests will be added after their question banks are prepared and reviewed.</p>`;
}
function openLevel(l){
 vocabLevel=l;kanjiLevel=l;v.innerHTML=`<div class="card"><button onclick="go('levels')">← All levels</button><h2>JLPT ${l} Learning Hub</h2><p>Choose what you want to study.</p><p><button class="p" onclick="go('vocab')">📚 ${l} Vocabulary</button></p><p><button class="p" onclick="go('kanji')">字 ${l} Kanji</button></p><p><button class="p" onclick="go('videos');setTimeout(()=>document.getElementById('playlist${l}')?.scrollIntoView({behavior:'smooth'}),50)">▶ ${l} Video Lessons</button></p>${l==="N5"?`<p class="note">N5 mock tests are available in the Mock Test section.</p>`:`<p class="note">Mock tests for ${l} are not available yet. The vocabulary, kanji starter library and video playlist can be opened now.</p>`}</div>`;
}
let ex=null;
function exam(){if(!ex){v.innerHTML=`<div class="card"><h3>JLPT N5 practice</h3><p class="note">The current release focuses on N5. These are original practice questions, not an official JLPT paper.</p><h3>Full N5 mock · 27 questions · 25 minutes</h3><p><button class="p" onclick="startFull()">Start full N5 mock</button></p><h3>Quick N5 vocabulary mock · 5 questions</h3><p><button onclick="startEx('N5')">Start quick N5 mock</button></p></div>${histCard()}`;return}
if(ex.i>=ex.q.length){const sc=Math.round(ex.s/ex.q.length*100);(S.mocks[ex.l]=S.mocks[ex.l]||[]).push(sc);save();const ps=sc>=70;ex=null;v.innerHTML=`<div class="card"><h2>${sc}% ${ps?"✅ Passed":"❌ Not passed"}</h2><p class="note">Only scores of 70%+ count toward unlocking.</p><button class="p" onclick="exam()">OK</button></div>`;return}
const [w,m]=ex.q[ex.i],all=W[ex.l].map(z=>z[1]),o=shuf([m,...shuf(all.filter(z=>z!==m)).slice(0,3)]);
v.innerHTML=`<div class="card"><p class="note">${ex.l} · ${ex.i+1}/${ex.q.length} · ${t("mean")}</p><div class="big">${w}</div><div class="ch">${o.map(z=>`<button onclick="exAns(${z===m})">${z}</button>`).join("")}</div></div>`}
