function makeN5Paper(paper){
 const D=N5_EXTRA_SOURCE, out=[];
 const pick=(arr,n,offset)=>Array.from({length:n},(_,i)=>arr[(offset+i)%arr.length]);
 const rotate=(a,k)=>a.slice(k%a.length).concat(a.slice(0,k%a.length));
 const vo=rotate(D.v,(paper-3)*15), go=rotate(D.g,(paper-3)*7);
 const ro=rotate(D.r,(paper-3)*3), ao=rotate(D.a,(paper-3)*5);
 for(let i=0;i<15;i++){
  const x=vo[i%vo.length], mode=Math.floor(i/5);
  if(mode===0) out.push(["Vocabulary",`「${x[0]}」の読み方は？`,[x[1],...x[3].slice(0,3)],0,`${x[0]}（${x[1]}）means ${x[2]}.`]);
  else if(mode===1) out.push(["Vocabulary",`「${x[0]}」の意味はどれですか。`,[x[2],...x[3]],0,`${x[0]}（${x[1]}）means ${x[2]}.`]);
  else out.push(["Vocabulary",`Which Japanese word means “${x[2]}”?`,[x[0],...D.v.filter(y=>y[0]!==x[0]).slice((paper*7+i*3)%D.v.length,(paper*7+i*3)%D.v.length+3).map(y=>y[0])],0,`${x[0]}（${x[1]}）means ${x[2]}.`]);
 }
 for(let i=0;i<15;i++){
  const x=go[i%go.length];
  const variant=Math.floor(i/5);
  const prompts=[
   x[0],
   x[0].replace("わたし","たなかさん"),
   x[0].replace("友達","先生").replace("学校","図書館")
  ];
  out.push(["Grammar",prompts[variant],[x[1],...x[2]],0,x[3]]);
 }
 for(let i=0;i<15;i++){
  const x=ro[i%ro.length];
  out.push(["Reading",x[0]+"\n"+x[1],[x[2],...x[3]],0,x[4]]);
 }
 for(let i=0;i<15;i++){
  const x=ao[i%ao.length], variant=Math.floor(i/ao.length);
  const q=x[0];
  out.push(["Listening",x[1],[x[2],...x[3]],0,x[4],q]);
 }
 return out;
}


