function makeN4Paper(paper){
 const D=N4_BANK_SOURCE, out=[];
 const rotate=(a,k)=>a.slice(k%a.length).concat(a.slice(0,k%a.length));
 const vv=rotate(D.v,(paper-1)*3), gg=rotate(D.g,(paper-1)*5);
 const rr=rotate(D.r,(paper-1)*2), aa=rotate(D.a,(paper-1)*3);
 for(let i=0;i<20;i++){
  const x=vv[i%vv.length], kind=i%2;
  if(kind===0)out.push(["Vocabulary",`「${x[0]}」の読み方は？`,[x[1],...x[3]],0,`${x[0]}（${x[1]}）means ${x[2]}.`]);
  else out.push(["Vocabulary",`「${x[0]}」の意味はどれですか。`,[x[2],...x[3]],0,`${x[0]}（${x[1]}）means ${x[2]}.`]);
 }
 for(let i=0;i<20;i++){const x=gg[i%gg.length];out.push(["Grammar",x[0],[x[1],...x[2]],0,x[3]]);}
 for(let i=0;i<10;i++){const x=rr[i%rr.length];out.push(["Reading",x[0]+"\n"+x[1],[x[2],...x[3]],0,x[4]]);}
 for(let i=0;i<10;i++){const x=aa[i%aa.length];out.push(["Listening",x[1],[x[2],...x[3]],0,x[4],x[0]]);}
 return out;
}


